INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (2.1, "2030/01/01 14:59:59", 1, 130011, 3001100, "2024/10/31 12:00:00", "ヤマト", 3001, -416.5, "ミッションねえ……\nちょうどいいや\nどこまで片付けられるか\n賭けをしようじゃないか", 2, 0.0, 100);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (5.68, "2030/01/01 14:59:59", 4, 130011, 3001101, "2024/10/31 12:00:00", "ヤマト", 3001, -416.5, "他人から言われた任務を\n言われるままにやるなんざ\n性に合わないんだがね……\nま、報酬は貰っとこうか", 2, 0.0, 101);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (0.0, "2030/01/01 14:59:59", 1, 130011, 3001102, "2024/10/31 12:00:00", "ヤマト", 3001, -416.5, "なんだい？　やれンなら\nとっとと済ませちまいな。\nフブキが早くやることやれ\nってボヤいてたよ。", 1, 0.0, 102);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (0.0, "2030/01/01 14:59:59", 1, 130211, 3002100, "2024/10/31 12:00:00", "フブキ", 3002, -416.5, "え～？　ぼくに頼みごと～？\nどうしちゃおっかな～\nちゃんとお願いできたら\n考えてあげよっかな～？", 1, 0.0, 100);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (0.0, "2030/01/01 14:59:59", 1, 130211, 3002101, "2024/10/31 12:00:00", "フブキ", 3002, -416.5, "ほらほらぁ、これが\n欲しいんでしょ～？\nほんと、しょうがないよね～\nザコおに～いさん♡", 1, 0.0, 101);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (8.53, "2030/01/01 14:59:59", 5, 130211, 3002102, "2024/10/31 12:00:00", "フブキ", 3002, -416.5, "へえ～、欲しいんだ～？\nぼくのた・い・せ・つ・な・モ・ノ\nあははっ！　なに考えてんの？\nもうへんふしじゃ～んｗ", 2, 0.0, 102);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (5.67, "2030/01/01 14:59:59", 7, 130211, 3002103, "2024/10/31 12:00:00", "フブキ", 3002, -416.5, "なになに～？　もしかしてまた\nおねだりするつもりなんだ？\nとか言って、ほんとはぼくに\n会いたいだけだったりして～？", 1, 0.0, 103);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (0.0, "2030/01/01 14:59:59", 1, 130211, 3002104, "2024/10/31 12:00:00", "フブキ", 3002, -416.5, "ザコお兄さんってぇ\n頼み方もワンパなのぉ～？\nもっと必死にならないと\nぼくの心は動かせないよ～？", 1, 0.0, 104);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (0.0, "2030/01/01 14:59:59", 3, 130211, 3002300, "2024/10/31 12:00:00", "フブキ", 3004, -416.5, "あのさーザコお兄さん、\nな～んか調子乗ってない？\nぼくのこと、なんでもくれる\nチョロいやつとか思ってたりー？", 3, 0.0, 300);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (0.0, "2030/01/01 14:59:59", 7, 130211, 3002400, "2024/10/31 12:00:00", "フブキ", 3005, -416.5, "ざんね～ん♪\nうざいお兄さんには、もうな～んにもあげませ～ん♡\nほんとなっさけなーい♪\nばいば～い♡", 7, 0.0, 301);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (4.4, "2030/01/01 14:59:59", 2, 130211, 3003200, "2024/10/31 12:00:00", "フブキ", 3003, -416.5, "きゃはは、ほんと必死～♡\nは～、面白かった。\n笑えたからいいよ～\nそれ、恵んだげる～♪", 1, 0.0, 200);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (0.0, "2030/01/01 14:59:59", 7, 130211, 3003201, "2024/10/31 12:00:00", "フブキ", 3003, -416.5, "は～、しょうがないな～♡\nザコお兄さんってば\nほんとよわよわで\n情けないよね～ｗ", 7, 0.0, 201);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (5.6, "2030/01/01 14:59:59", 1, 130211, 3003202, "2024/10/31 12:00:00", "フブキ", 3003, -416.5, "お兄さんってば、ぼくがいないと\nほんとザッコザコだよね～\nもっと感謝しろし～♪", 2, 0.0, 202);
